import{_ as l,a0 as o,w as d,s as c,ao as p,I as n,x as a,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"一些被忽略的 Git 知识 | LCTT x X-CMD","titleTemplate":false,"description":"一些被忽略的 Git 知识 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些被忽略的 Git 知识 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些被忽略的 Git 知识 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20231020 Some miscellaneous git facts","title":"一些被忽略的 Git 知识","tag":"202310","desc":""},"relativePath":"202310/20231020 Some miscellaneous git facts.md","filePath":"[post].md"}'),r={name:"202310/20231020 Some miscellaneous git facts.md"};function g(h,s,f,u,b,k){const e=o("Link");return d(),c("div",null,[s[20]||(s[20]=p(`<h1 id="一些被忽略的-git-知识" tabindex="-1">一些被忽略的 Git 知识 <a class="header-anchor" href="#一些被忽略的-git-知识" aria-label="Permalink to “一些被忽略的 Git 知识”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/25/122259mfu0uowyppuyfdyo.jpg" alt=""></p><p>我一直在慢慢地撰写关于 Git 工作原理的文章。尽管我曾认为自己对 Git 非常了解，但像往常一样，当我尝试解释某事的时候，我又学到一些新东西。</p><p>现在回想起来，这些事情都不算太令人吃惊，但我以前并没有清楚地思考过它们。</p><p>事实是:</p><ul><li>“索引”、“暂存区” 和 <code>-cached</code> 是一回事</li><li>隐匿文件就是一堆提交</li><li>并非所有引用都是分支或标签</li><li>合并提交不是空的</li></ul><p>下面我们来详细了解这些内容。</p><h3 id="索引-、-暂存区-和-cached-是一回事" tabindex="-1">“索引”、“暂存区” 和 <code>-cached</code> 是一回事 <a class="header-anchor" href="#索引-、-暂存区-和-cached-是一回事" aria-label="Permalink to ““索引”、“暂存区” 和 -cached 是一回事”">​</a></h3><p>当你运行 <code>git add file.txt</code>，然后运行 <code>git status</code>，你会看到类似以下的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add content/post/2023-10-20-some-miscellaneous-git-facts.markdown</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>Changes to be committed:</span></span>
<span class="line"><span>    (use &quot;git restore --staged &lt;file&gt;...&quot; to unstage)</span></span>
<span class="line"><span>    new file:   content/post/2023-10-20-some-miscellaneous-git-facts.markdown</span></span></code></pre></div><p>人们通常称这个过程为“暂存文件”或“将文件添加到暂存区”。</p><p>当你使用 <code>git add</code> 命令来暂存文件时，Git 在后台将文件添加到其对象数据库（在 <code>.git/objects</code> 目录下），并更新一个名为 <code>.git/index</code> 的文件以引用新添加的文件。</p><p>Git 中的这个“暂存区”事实上有 3 种不同的名称，但它们都指的是同一个东西（即 <code>.git/index</code> 文件）：</p><ul><li><code>git diff --cached</code></li><li><code>git diff --staged</code></li><li><code>.git/index</code> 文件</li></ul><p>我觉得我早该早点认识到这一点，但我之前并没有，所以在这里提醒一下。</p><h3 id="隐匿文件就是一堆提交" tabindex="-1">隐匿文件就是一堆提交 <a class="header-anchor" href="#隐匿文件就是一堆提交" aria-label="Permalink to “隐匿文件就是一堆提交”">​</a></h3><p>当我运行 <code>git stash</code> 命令来保存更改时，我一直对这些更改究竟去了哪里感到有些困惑。事实上，当你运行 <code>git stash</code> 命令时，Git 会根据你的更改创建一些提交，并用一个名为 <code>stash</code> 的引用来标记它们（在 <code>.git/refs/stash</code> 目录下）。</p><p>让我们将此博客文章隐匿起来，然后查看 <code>stash</code> 引用的日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log stash --oneline</span></span>
<span class="line"><span>6cb983fe (refs/stash) WIP on main: c6ee55ed wip</span></span>
<span class="line"><span>2ff2c273 index on main: c6ee55ed wip</span></span>
<span class="line"><span>... some more stuff</span></span></code></pre></div><p>现在我们可以查看提交 <code>2ff2c273</code> 以查看其包含的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show 2ff2c273  --stat</span></span>
<span class="line"><span>commit 2ff2c273357c94a0087104f776a8dd28ee467769</span></span>
<span class="line"><span>Author: Julia Evans &lt;julia@jvns.ca&gt;</span></span>
<span class="line"><span>Date:   Fri Oct 20 14:49:20 2023 -0400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    index on main: c6ee55ed wip</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    content/post/2023-10-20-some-miscellaneous-git-facts.markdown | 40 ++++++++++++++++++++++++++++++++++++++++</span></span></code></pre></div><p>毫不意外，它包含了这篇博客文章。这很合理！</p><p>实际上，<code>git stash</code> 会创建两个独立的提交：一个是索引提交，另一个是你尚未暂存的改动提交。这让我感到很振奋，因为我一直在开发一款工具，用于快照和恢复 Git 仓库的状态（也许永远不会发布），而我提出的设计与 Git 的隐匿实现非常相似，所以我对自己的选择感到满意。</p><p>显然 <code>stash</code> 中的旧提交存储在 reflog 中。</p><h3 id="并非所有引用都是分支或标签" tabindex="-1">并非所有引用都是分支或标签 <a class="header-anchor" href="#并非所有引用都是分支或标签" aria-label="Permalink to “并非所有引用都是分支或标签”">​</a></h3><p>Git 文档中经常泛泛地提到 “引用”，这使得我有时觉得很困惑。就个人而言，我在 Git 中处理 “引用” 的 99% 时间是指分支或 HEAD，而剩下的 1% 时间是指标签。事实上，我以前完全不知道任何不是分支、标签或 <code>HEAD</code> 的引用示例。</p><p>但现在我知道了一个例子—— <code>stash</code> 是一种引用，而它既不是分支也不是标签！所以这太酷啦！</p><p>以下是我博客的 Git 仓库中的所有引用（除了 <code>HEAD</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find .git/refs -type f</span></span>
<span class="line"><span>.git/refs/heads/main</span></span>
<span class="line"><span>.git/refs/remotes/origin/HEAD</span></span>
<span class="line"><span>.git/refs/remotes/origin/main</span></span>
<span class="line"><span>.git/refs/stash</span></span></code></pre></div><p>人们在本帖回复中提到的其他一些参考资料：</p>`,30)),n("ul",null,[n("li",null,[s[1]||(s[1]=n("code",null,"refs/notes/*",-1)),s[2]||(s[2]=a("，来自 ",-1)),i(e,{href:"https://tylercipriani.com/blog/2022/11/19/git-notes-gits-coolest-most-unloved-feature/"},{default:t(()=>[...s[0]||(s[0]=[n("code",null,"git notes",-1)])]),_:1})]),s[3]||(s[3]=n("li",null,[n("code",null,"refs/pull/123/head"),a(" 和 "),n("code",null,"refs/pull/123/head`` 用于 GitHub 拉取请求（可通过 "),a("git fetch origin refs/pull/123/merge` 获取）")],-1)),s[4]||(s[4]=n("li",null,[n("code",null,"refs/bisect/*"),a("，来自 "),n("code",null,"git bisect")],-1))]),s[21]||(s[21]=p(`<h3 id="合并提交不是空的" tabindex="-1">合并提交不是空的 <a class="header-anchor" href="#合并提交不是空的" aria-label="Permalink to “合并提交不是空的”">​</a></h3><p>这是一个示例 Git 仓库，其中我创建了两个分支 <code>x</code> 和 <code>y</code>，每个分支都有一个文件（<code>x.txt</code> 和 <code>y.txt</code>），然后将它们合并。让我们看看合并提交。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>96a8afb (HEAD -&gt; y) Merge branch &#39;x&#39; into y</span></span>
<span class="line"><span>0931e45 y</span></span>
<span class="line"><span>1d8bd2d (x) x</span></span></code></pre></div><p>如果我运行 <code>git show 96a8afb</code>，合并提交看起来是“空的”：没有差异！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git show 96a8afb</span></span>
<span class="line"><span>commit 96a8afbf776c2cebccf8ec0dba7c6c765ea5d987 (HEAD -&gt; y)</span></span>
<span class="line"><span>Merge: 0931e45 1d8bd2d</span></span>
<span class="line"><span>Author: Julia Evans &lt;julia@jvns.ca&gt;</span></span>
<span class="line"><span>Date:   Fri Oct 20 14:07:00 2023 -0400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Merge branch &#39;x&#39; into y</span></span></code></pre></div><p>但是，如果我单独比较合并提交与其两个父提交之间的差异，你会发现当然<strong>有</strong>差异：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git diff 0931e45 96a8afb   --stat</span></span>
<span class="line"><span>    x.txt | 1 +</span></span>
<span class="line"><span>    1 file changed, 1 insertion(+)</span></span>
<span class="line"><span>$ git diff 1d8bd2d 96a8afb   --stat</span></span>
<span class="line"><span>    y.txt | 1 +</span></span>
<span class="line"><span>    1 file changed, 1 insertion(+)</span></span></code></pre></div><p>现在回想起来，合并提交并不是实际上“空的”（它们是仓库当前状态的快照，就像任何其他提交一样），这一点似乎很明显，只是我以前从未思考为什么它们看起来为空。</p><p>显然，这些合并差异为空的原因是合并差异只显示<strong>冲突</strong> —— 如果我创建一个带有合并冲突的仓库（一个分支在同一文件中添加了 <code>x</code>，而另一个分支添加了 <code>y</code>），然后查看我解决冲突的合并提交，它看起来会像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show HEAD</span></span>
<span class="line"><span>commit 3bfe8311afa4da867426c0bf6343420217486594</span></span>
<span class="line"><span>Merge: 782b3d5 ac7046d</span></span>
<span class="line"><span>Author: Julia Evans &lt;julia@jvns.ca&gt;</span></span>
<span class="line"><span>Date:   Fri Oct 20 15:29:06 2023 -0400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Merge branch &#39;x&#39; into y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>diff --cc file.txt</span></span>
<span class="line"><span>index 975fbec,587be6b..b680253</span></span>
<span class="line"><span>--- a/file.txt</span></span>
<span class="line"><span>+++ b/file.txt</span></span>
<span class="line"><span>@@@ -1,1 -1,1 +1,1 @@@</span></span>
<span class="line"><span>- y</span></span>
<span class="line"><span>    -x</span></span>
<span class="line"><span>++z</span></span></code></pre></div><p>这似乎是在告诉我，一个分支添加了 <code>x</code>，另一个分支添加了 <code>y</code>，合并提交通过将 <code>z</code> 替代冲突解决了它。但在前面的示例中，没有冲突，所以 Git 并未显示任何差异。</p><p>（感谢 Jordi 告诉我合并差异的工作原理）</p><h3 id="先这样吧" tabindex="-1">先这样吧 <a class="header-anchor" href="#先这样吧" aria-label="Permalink to “先这样吧”">​</a></h3><p>些写到这里吧，也许我将在学到更多 Git 知识时撰写另一篇关于 Git 的知识的博客文章。</p><p><em>（题图：MJ/03bfecc3-944e-47a0-a4fd-575293d2ba92）</em></p><hr>`,16)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),i(e,{href:"https://jvns.ca/blog/2023/10/20/some-miscellaneous-git-facts/"},{default:t(()=>[...s[5]||(s[5]=[a("https://jvns.ca/blog/2023/10/20/some-miscellaneous-git-facts/",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),i(e,{href:"https://jvns.ca/"},{default:t(()=>[...s[7]||(s[7]=[a("Julia Evans",-1)])]),_:1}),s[12]||(s[12]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),i(e,{href:"https://github.com/KaguyaQiang"},{default:t(()=>[...s[9]||(s[9]=[a("KaguyaQiang",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const C=l(r,[["render",g]]);export{y as __pageData,C as default};
